def maximum_split_tree_product(root):
    sums=[]
    def total(node):
        if node is None:return 0
        value=node.val+total(node.left)+total(node.right);sums.append(value);return value
    whole=total(root)
    return max(value*(whole-value) for value in sums[:-1])%(10**9+7)

